insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('c2c53845-b6c1-4601-b274-4b3a283c8cc5', 'ac4099c8-be35-4249-a230-cc82d50ba673', $$f(x) = 3 + ²log(x + 4); A snijpunt van de grafiek van f met de x-as$$,
   $$wiskunde-b-havo-2022-ii-logaritme-en-parabool-context1.png$$,
   $$De functie f wordt gegeven door f(x) = 3 + ²log(x + 4). De grafiek van f snijdt de x-as in het punt A.$$, 'inline'),
  ('171655e8-729e-431e-a376-7b216c76b3cc', 'ac4099c8-be35-4249-a230-cc82d50ba673', $$f(x) is te herschrijven als f(x) = ²log(ax + b)$$,
   $$wiskunde-b-havo-2022-ii-logaritme-en-parabool-context2.png$$,
   $$Het functievoorschrift f(x) = 3 + ²log(x + 4) is te herschrijven in de vorm f(x) = ²log(ax + b).$$, 'inline'),
  ('0a4b7a9b-bfeb-4903-b8bb-60e6d47f823a', 'ac4099c8-be35-4249-a230-cc82d50ba673', $$S snijpunt met de y-as, T snijpunt van de verticale asymptoot met de x-as; parabool g met top T door S; figuur$$,
   $$wiskunde-b-havo-2022-ii-logaritme-en-parabool-context3.png$$,
   $$De grafiek van f snijdt de y-as in het punt S. De grafiek van f heeft een verticale asymptoot. Deze asymptoot snijdt de x-as in het punt T.
De functie g is een kwadratische functie. De grafiek is dus een parabool. Punt T is de top van de parabool. De parabool gaat bovendien door S. Zie de figuur.
figuur$$, 'inline'),
  ('19cecee3-5502-4fab-b965-df28afb3a66f', '09129be3-1745-4066-bafe-8cc8195fa763', $$kaart van het Gooi (1723) met netwerk van driehoeken tussen kerktorens$$,
   $$wiskunde-b-havo-2022-ii-gooilandkaart-context1.png$$,
   $$In 1723 heeft landmeter M. Walraven onderstaande kaart van het Gooi gemaakt. De hoekpunten van de driehoeken op de kaart zijn vaak de kerktorens van de dorpen. Met behulp van een hoekmeetinstrument heeft Walraven enkele hoeken zeer nauwkeurig opgemeten. Verder zijn twee hemelsbrede afstanden bepaald. Met het netwerk van driehoeken op de kaart kunnen zo de afstanden tussen de kerktorens berekend worden.$$, 'inline'),
  ('9c5f358d-c4fd-4887-9f22-d4af10f924f0', '09129be3-1745-4066-bafe-8cc8195fa763', $$metingen: Laren-Hilversum 5060 m, Naarden-Huizen 4810 m, hoeken 90,9°, 49,3° en 47,7°; figuur (vergroot op de uitwerkbijlage)$$,
   $$wiskunde-b-havo-2022-ii-gooilandkaart-context2.png$$,
   $$In 1723 zijn de volgende metingen gedaan: – De afstand tussen (de kerktorens van) Laren en Hilversum is 5060 meter. – De afstand tussen (de kerktorens van) Naarden en Huizen is 4810 meter. – De hoek tussen Laren-Hilversum en Laren-Naarden is 90,9°. – De hoek tussen Hilversum-Laren en Hilversum-Naarden is 49,3°. – De hoek tussen Naarden-Huizen en Naarden-Laren is 47,7°. Zie de figuur. Deze figuur staat vergroot op de uitwerkbijlage.
figuur$$, 'inline'),
  ('9e6c6510-3d5f-49f5-ac3e-042754f5d9e5', '09129be3-1745-4066-bafe-8cc8195fa763', $$uitwerkbijlage bij vraag 4: vergrote kaart met netwerk van driehoeken$$,
   $$wiskunde-b-havo-2022-ii-gooilandkaart-context3.png$$,
   $$uitwerkbijlage bij vraag 4: vergrote kaart van het Gooi met het netwerk van driehoeken$$, 'uitwerkbijlage'),
  ('883d7824-1ad5-45fa-8a5f-7cf991ac2b9b', '43804dc4-a1f3-46c4-89d0-87f7b08e63a3', $$f(x) = √(3x + 4); figuur 1; grafiek van f ontstaat uit y = √x door horizontale translatie en vermenigvuldiging t.o.v. de y-as$$,
   $$wiskunde-b-havo-2022-ii-wortel-en-cirkel-context1.png$$,
   $$De functie f wordt gegeven door f(x) = √(3x + 4). In figuur 1 is de grafiek van f weergegeven.
figuur 1
De grafiek van f ontstaat uit de grafiek van y = √x door een horizontale translatie en een vermenigvuldiging ten opzichte van de y-as.$$, 'inline'),
  ('3e946294-11a7-4eb8-badf-a610c845fff6', '43804dc4-a1f3-46c4-89d0-87f7b08e63a3', $$A(0, 2); k raaklijn in A, l loodrecht op k in A, M snijpunt van l met de x-as; cirkel c met middelpunt M raakt f in A; P en Q snijpunten van c met de x-as; figuur 2$$,
   $$wiskunde-b-havo-2022-ii-wortel-en-cirkel-context2.png$$,
   $$De grafiek van f snijdt de y-as in het punt A(0, 2). De lijn k is de raaklijn aan de grafiek van f in A. De lijn l snijdt lijn k loodrecht in A. Het punt M is het snijpunt van l met de x-as.
De cirkel c heeft punt M als middelpunt en raakt de grafiek van f in punt A. Lijn k is dus ook de raaklijn in A aan c. De punten P en Q zijn de snijpunten van cirkel c met de x-as. Zie figuur 2.
figuur 2$$, 'inline'),
  ('ee0061e1-e5ac-4bfd-82cf-123098d92176', '814b19d4-5ce7-41a7-9ed3-f13cdb8f7076', $$f(x) = 1 + 3sin(2x), g(x) = 1 + 3cos(2x); P eerste top van f en R eerste top van g rechts van de y-as; lijnstuk PR; figuur 1$$,
   $$wiskunde-b-havo-2022-ii-sinusoiden-en-somfunctie-context1.png$$,
   $$De functies f en g worden gegeven door:
f(x) = 1 + 3sin(2x)
g(x) = 1 + 3cos(2x)
Het punt P is de eerste top van de grafiek van f rechts van de y-as en het punt R is de eerste top van de grafiek van g rechts van de y-as.
Zie figuur 1, waarin ook het lijnstuk PR getekend is.
figuur 1$$, 'inline'),
  ('f5a45513-d308-41f4-89b3-8a15ed9fcda1', '814b19d4-5ce7-41a7-9ed3-f13cdb8f7076', $$somfunctie h(x) = f(x) + g(x) is een sinusoïde; figuur 2; h(x) = p + q · cos(r(x − s))$$,
   $$wiskunde-b-havo-2022-ii-sinusoiden-en-somfunctie-context2.png$$,
   $$De grafiek van de somfunctie h(x) = f(x) + g(x) blijkt ook een sinusoïde te zijn. Zie figuur 2.
figuur 2
Het functievoorschrift van h is te schrijven als:
h(x) = p + q · cos(r(x − s))$$, 'inline'),
  ('87d88eb5-b46b-4396-8b48-9510b4252745', 'e3b731ab-b717-4c6d-9356-2d2694575230', $$Air Quality Index (AQI) berekend uit ozonconcentratie C in ppm$$,
   $$wiskunde-b-havo-2022-ii-luchtvervuiling-context1.png$$,
   $$De Air Quality Index (AQI) is een waarde die overheden gebruiken om aan te geven hoe vervuild de lucht is: hoe hoger de AQI, des te sterker is de luchtvervuiling. De AQI wordt berekend uit de ozonconcentratie C in ppm. De ppm is een veelgebruikte eenheid voor concentratie.$$, 'inline'),
  ('41fdce1b-3baa-4612-b2f4-986afa8fd529', 'e3b731ab-b717-4c6d-9356-2d2694575230', $$tabel: categorieën luchtkwaliteit met bereik van C (ppm) en AQI; binnen elke categorie stijgend lineair verband$$,
   $$wiskunde-b-havo-2022-ii-luchtvervuiling-context2.png$$,
   $$Men heeft de mogelijke waarden van de AQI in categorieën opgedeeld. In de tabel is voor elke categorie luchtkwaliteit te zien welke waarden van C en de AQI daarbij horen. Zo is de laagste waarde van de AQI in de categorie ‘gemiddeld’ gelijk aan 50 en dat is het geval als C = 0,065.
tabel categorie luchtkwaliteit C (ppm) AQI goed 0 – 0,065 0 – 50 gemiddeld 0,065 – 0,085 50 – 100 ongezond voor kinderen en ouderen 0,085 – 0,105 100 – 150 ongezond 0,105 – 0,125 150 – 200 erg ongezond 0,125 – 0,375 200 – 300
Binnen elke afzonderlijke categorie is er een stijgend lineair verband tussen de AQI en C.$$, 'inline'),
  ('873948eb-1c6a-436a-9469-c65fc690bcb4', 'e3b731ab-b717-4c6d-9356-2d2694575230', $$gemeten ozonconcentratie 0,20 ppm$$,
   $$wiskunde-b-havo-2022-ii-luchtvervuiling-context3.png$$,
   $$Op een bepaalde plek wordt een ozonconcentratie gemeten van 0,20 ppm.$$, 'inline'),
  ('53056936-c8f1-4454-92fe-81be9ef6bdd8', 'e3b731ab-b717-4c6d-9356-2d2694575230', $$omrekenformule C(mg/m³) = 584,976 · C(ppm) / (273,15 + T), T temperatuur in °C$$,
   $$wiskunde-b-havo-2022-ii-luchtvervuiling-context4.png$$,
   $$In plaats van de concentratie in ppm te geven, kan deze ook in milligram per kubieke meter (mg/m³) gegeven worden. Als de temperatuur bekend is, kan de concentratie van ppm naar mg/m³ omgerekend worden. Daarvoor geldt de volgende formule:
C(mg/m³) = (584,976 · C(ppm)) / (273,15 + T) met T de temperatuur in graden Celsius$$, 'inline'),
  ('d0e45522-ca9e-4d42-83c7-780d05dd023e', 'e3b731ab-b717-4c6d-9356-2d2694575230', $$Amsterdam 2015: 0,0612 mg/m³ bij 20 °C$$,
   $$wiskunde-b-havo-2022-ii-luchtvervuiling-context5.png$$,
   $$Op zeker moment in 2015 werd in Amsterdam een ozonconcentratie van 0,0612 mg/m³ gemeten. De temperatuur was op dat moment 20 graden Celsius.$$, 'inline'),
  ('f87460ac-8453-431f-91e5-52b2f377d158', 'e3b731ab-b717-4c6d-9356-2d2694575230', $$bij constant 25 °C is het verband tussen C(ppm) en C(mg/m³) recht evenredig$$,
   $$wiskunde-b-havo-2022-ii-luchtvervuiling-context6.png$$,
   $$Als de temperatuur constant 25 graden blijft, dan is het verband tussen C(ppm) en C(mg/m³) recht evenredig.$$, 'inline'),
  ('16f2baf8-a250-4ba8-9f72-53aae43c3748', '0c8f2868-0a04-4bd8-bb30-aa6ffb2cd109', $$f(x) = 3/x³ met x > 0$$,
   $$wiskunde-b-havo-2022-ii-minimale-omtrek-context1.png$$,
   $$De functie f wordt gegeven door f(x) = 3/x³ met x > 0.$$, 'inline'),
  ('da2a4d72-8e3e-4f81-b9bd-dee4c82faf13', '0c8f2868-0a04-4bd8-bb30-aa6ffb2cd109', $$P op de grafiek van f; rechthoek met hoekpunten P en O; figuur 1 met P(1, 3) en figuur 2 met P(2, 3/8)$$,
   $$wiskunde-b-havo-2022-ii-minimale-omtrek-context2.png$$,
   $$Punt P is een willekeurig punt op de grafiek van f. Bij zo''n punt P kun je een rechthoek tekenen met horizontale en verticale zijden en hoekpunten P en O. In figuur 1 is de rechthoek getekend als P het punt (1, 3) is en in figuur 2 is de rechthoek getekend als P het punt (2, 3/8) is.
figuur 1 figuur 2$$, 'inline'),
  ('42279322-bdd3-40d7-a45f-f60b484eaedb', '0c8f2868-0a04-4bd8-bb30-aa6ffb2cd109', $$omtrek hangt af van de keuze van P; P zó kiezen dat de omtrek minimaal is$$,
   $$wiskunde-b-havo-2022-ii-minimale-omtrek-context3.png$$,
   $$De omtrek van de rechthoek in figuur 1 is groter dan de omtrek van de rechthoek in figuur 2. De omtrek is dus afhankelijk van de keuze van P.
Je kunt P zó op de grafiek van f kiezen, dat de omtrek van de bijbehorende rechthoek minimaal is.$$, 'inline'),
  ('6803ad0d-44c7-40c7-bc0a-3cf1a9de943c', '2aa54504-a287-4b61-8d51-b0b800db02e0', $$f(x) = −2 + √(8 + x); A snijpunt met de x-as; k raakt de grafiek van f in A; figuur 1$$,
   $$wiskunde-b-havo-2022-ii-een-raaklijn-en-een-evenwijdige-lijn-door-o-context1.png$$,
   $$De functie f wordt gegeven door f(x) = −2 + √(8 + x). Het punt A is het snijpunt van de grafiek van f met de x-as. De lijn k raakt de grafiek van f in het punt A. Zie figuur 1.
figuur 1$$, 'inline'),
  ('73e6fb3e-464d-4740-9c22-c4c9be94d2d0', '2aa54504-a287-4b61-8d51-b0b800db02e0', $$een vergelijking van k is y = ¼x + 1$$,
   $$wiskunde-b-havo-2022-ii-een-raaklijn-en-een-evenwijdige-lijn-door-o-context2.png$$,
   $$Een vergelijking van k is y = ¼x + 1.$$, 'inline'),
  ('3b4c0cb1-6fa9-41f3-b0da-dfda6c91daa9', '2aa54504-a287-4b61-8d51-b0b800db02e0', $$B randpunt van de grafiek van f; l lijn door B en O; figuur 2$$,
   $$wiskunde-b-havo-2022-ii-een-raaklijn-en-een-evenwijdige-lijn-door-o-context3.png$$,
   $$Het punt B is het randpunt van de grafiek van f. Lijn l is de lijn door B en de oorsprong O. Zie figuur 2.
figuur 2$$, 'inline'),
  ('819dd507-5ae2-4c4f-8427-a2029da0b05b', '2aa54504-a287-4b61-8d51-b0b800db02e0', $$lijnen k en l zijn evenwijdig$$,
   $$wiskunde-b-havo-2022-ii-een-raaklijn-en-een-evenwijdige-lijn-door-o-context4.png$$,
   $$Lijnen k en l zijn evenwijdig.$$, 'inline'),
  ('efb18b67-73bf-4c41-ae65-699bdb14da71', '295ed628-dca9-4606-96a1-f2144b5193ad', $$daglengte L in Luxemburg (uren) als functie van t (dagen, t = 0 op 1 januari); L(t) = 12 + 4,1 sin(a(t − b)); figuur; periode 365 dagen, langste dag op t = 168$$,
   $$wiskunde-b-havo-2022-ii-daglengte-context1.png$$,
   $$De daglengte is het aantal uren tussen zonsopgang en zonsondergang. De daglengte verandert in de loop van het jaar en varieert ook per plaats op aarde. Gedurende een jaar is voor elke dag in Luxemburg de daglengte bepaald. Bij deze waarnemingen is een zo goed mogelijk passend model opgesteld en vervolgens is daarbij de grafiek getekend. Zie de figuur. Hierbij is de daglengte L in Luxemburg in uren gegeven als functie van de tijd t in dagen met t = 0 op 1 januari. Het functievoorschrift dat bij dit model hoort, ziet er als volgt uit:
L(t) = 12 + 4,1 sin(a(t − b))
figuur
De periode van het model is 365 dagen en de langste dag is op t = 168.$$, 'inline'),
  ('5c8e88ee-2776-4c10-bdff-de9a610c9f23', '295ed628-dca9-4606-96a1-f2144b5193ad', $$toename daglengte het grootst als de helling van de grafiek van L maximaal is; figuur op de uitwerkbijlage$$,
   $$wiskunde-b-havo-2022-ii-daglengte-context2.png$$,
   $$De toename van de daglengte volgens het model is het grootst als de helling van de grafiek van L maximaal is. Met behulp van de figuur op de uitwerkbijlage kun je de maximale helling bepalen.$$, 'inline'),
  ('b69e9ca8-f8cc-447d-b559-1858c34e0682', '295ed628-dca9-4606-96a1-f2144b5193ad', $$uitwerkbijlage bij vraag 17: grafiek van L (gedraaid weergegeven)$$,
   $$wiskunde-b-havo-2022-ii-daglengte-context3.png$$,
   $$uitwerkbijlage bij vraag 17: grafiek van de daglengte L (in uren) tegen t (in dagen), gedraaid weergegeven$$, 'uitwerkbijlage'),
  ('90b5e16a-5dd3-45d0-a73d-3844beb7c2ec', '9c6350bb-774b-4956-8ec5-23a53f169eae', $$A(−3, 3) op l: y = −x, B(3, 3) op k: y = x; halve cirkel met diameter AB en middelpunt M$$,
   $$wiskunde-b-havo-2022-ii-vierkant-en-halve-cirkel-context1.png$$,
   $$Het punt A(−3, 3) ligt op lijn l met vergelijking y = −x en het punt B(3, 3) ligt op lijn k met vergelijking y = x. Door de punten A en B gaat een halve cirkel met diameter AB en middelpunt M.$$, 'inline'),
  ('5e51499d-49ef-42ce-bb3d-fee1a4f8024f', '9c6350bb-774b-4956-8ec5-23a53f169eae', $$vierkant OPQR: R op l, P op k, PQ raakt de halve cirkel in K; figuur (ook op de uitwerkbijlage)$$,
   $$wiskunde-b-havo-2022-ii-vierkant-en-halve-cirkel-context2.png$$,
   $$Voor vierkant OPQR geldt: – R ligt op l en P ligt op k. – Zijde PQ raakt de halve cirkel in het punt K. Zie de figuur. Deze figuur staat ook op de uitwerkbijlage.
figuur$$, 'inline'),
  ('1540c7b3-0d3a-47cb-b3d7-e58ce57ef09a', '9c6350bb-774b-4956-8ec5-23a53f169eae', $$uitwerkbijlage bij vraag 18: figuur met halve cirkel en vierkant OPQR$$,
   $$wiskunde-b-havo-2022-ii-vierkant-en-halve-cirkel-context3.png$$,
   $$uitwerkbijlage bij vraag 18: figuur met de halve cirkel en het vierkant OPQR$$, 'uitwerkbijlage');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('f955aa22-4051-471f-a945-6cb94b3c64f1', 'ac4099c8-be35-4249-a230-cc82d50ba673', 1,
