   $$wiskunde-b-havo-2022-ii-logaritme-en-parabool-vraag1.png$$, $$3p 1 Bereken exact de x-coördinaat van A.$$, array['c2c53845-b6c1-4601-b274-4b3a283c8cc5']::uuid[]),
  ('e6500667-336a-453b-92fa-18a1737d2f8a', 'ac4099c8-be35-4249-a230-cc82d50ba673', 2,
   '[{"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Standaardfuncties"}]'::jsonb,
   '["rekenregels logaritmen", "formule herschrijven", "logaritmische functie", "exact berekenen"]'::jsonb,
   $$Met de rekenregels voor logaritmen een functievoorschrift herschrijven tot één logaritme.$$,
   $$wiskunde-b-havo-2022-ii-logaritme-en-parabool-vraag2.png$$, $$2p 2 Bereken exact de waarden van a en b.$$, array['c2c53845-b6c1-4601-b274-4b3a283c8cc5', '171655e8-729e-431e-a376-7b216c76b3cc']::uuid[]),
  ('97c49aeb-2fae-48a4-b07f-6921afef42fd', 'ac4099c8-be35-4249-a230-cc82d50ba673', 3,
   '[{"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Standaardfuncties"}, {"domain": "Functies, grafieken en vergelijkingen", "subdomain": "Vergelijkingen en ongelijkheden"}]'::jsonb,
   '["verticale asymptoot", "snijpunt met de y-as", "kwadratische functie", "topformule", "functievoorschrift opstellen", "exact berekenen"]'::jsonb,
   $$Asymptoot en snijpunt met de y-as van een logaritmische functie bepalen en daarmee exact een parabool in topvorm opstellen.$$,
   $$wiskunde-b-havo-2022-ii-logaritme-en-parabool-vraag3.png$$, $$5p 3 Stel op exacte wijze een functievoorschrift van g op.$$, array['c2c53845-b6c1-4601-b274-4b3a283c8cc5', '0a4b7a9b-bfeb-4903-b8bb-60e6d47f823a']::uuid[]),
  ('089638ac-b685-453d-bb45-eea72bf9f5e3', '09129be3-1745-4066-bafe-8cc8195fa763', 4,
   '[{"domain": "Meetkundige berekeningen", "subdomain": "Afstanden en hoeken in concrete situaties"}]'::jsonb,
   '["sinusregel", "cosinusregel", "hoekensom driehoek", "driehoeksmeting", "afstand berekenen", "afronden"]'::jsonb,
   $$Met de sinusregel en de cosinusregel in een netwerk van driehoeken een onbekende afstand berekenen.$$,
   $$wiskunde-b-havo-2022-ii-gooilandkaart-vraag4.png$$, $$6p 4 Bereken de afstand tussen (de kerktorens van) Huizen en Hilversum. Geef je eindantwoord in tientallen meters nauwkeurig. Je kunt bij het beantwoorden van deze vraag de figuur op de uitwerkbijlage gebruiken.$$, array['19cecee3-5502-4fab-b965-df28afb3a66f', '9c5f358d-c4fd-4887-9f22-d4af10f924f0', '9e6c6510-3d5f-49f5-ac3e-042754f5d9e5']::uuid[]),
