   $$wiskunde-b-havo-2022-ii-sinusoiden-en-somfunctie-vraag7.png$$, $$4p 7 Bereken algebraïsch de lengte van lijnstuk PR. Geef je eindantwoord in twee decimalen.$$, array['ee0061e1-e5ac-4bfd-82cf-123098d92176']::uuid[]),
