   $$wiskunde-b-havo-2022-ii-sinusoiden-en-somfunctie-vraag8.png$$, $$7p 8 Bereken mogelijke waarden van p, q, r en s. Geef je eindantwoorden, indien nodig, in twee decimalen.$$, array['ee0061e1-e5ac-4bfd-82cf-123098d92176', 'f5a45513-d308-41f4-89b3-8a15ed9fcda1']::uuid[]),
