   $$wiskunde-b-havo-2022-ii-luchtvervuiling-vraag9.png$$, $$4p 9 Bereken de bijbehorende AQI. Geef je eindantwoord als geheel getal.$$, array['87d88eb5-b46b-4396-8b48-9510b4252745', '41fdce1b-3baa-4612-b2f4-986afa8fd529', '873948eb-1c6a-436a-9469-c65fc690bcb4']::uuid[]),
