   $$wiskunde-b-havo-2022-ii-luchtvervuiling-vraag10.png$$, $$4p 10 Bepaal de categorie luchtkwaliteit op dat moment.$$, array['87d88eb5-b46b-4396-8b48-9510b4252745', '41fdce1b-3baa-4612-b2f4-986afa8fd529', '53056936-c8f1-4454-92fe-81be9ef6bdd8', 'd0e45522-ca9e-4d42-83c7-780d05dd023e']::uuid[]),
