   $$wiskunde-b-havo-2022-ii-daglengte-vraag16.png$$, $$2p 16 Bepaal de waarden van a en b. Geef de waarde van a in drie decimalen en de waarde van b als geheel getal.$$, array['efb18b67-73bf-4c41-ae65-699bdb14da71']::uuid[]),
