   $$wiskunde-b-havo-2022-ii-vierkant-en-halve-cirkel-vraag18.png$$, $$5p 18 Bereken exact de coördinaten van K. Je kunt hierbij de figuur op de uitwerkbijlage gebruiken.$$, array['90b5e16a-5dd3-45d0-a73d-3844beb7c2ec', '5e51499d-49ef-42ce-bb3d-fee1a4f8024f', '1540c7b3-0d3a-47cb-b3d7-e58ce57ef09a']::uuid[]);
